# Body symmetry across animals (organisms generated by wikibio.zoomorph; dashed lines are planes of
# symmetry; cross-sections by wikibio.zoology). Sponges are asymmetrical and lack true tissue layers.
# Cnidarians are radial: a moon jelly (Aurelia) is tetramerous, with four planes through its oral arms
# (perradii) and gonads (interradii). Ctenophores are biradial: only the tentacular and stomodeal
# (pharyngeal) planes divide the body into mirror halves. Both are diploblastic. Echinoderms are
# pentaradial as adults (five planes, each through an arm and the opposite interradius; the madreporite
# in one interradius breaks the symmetry), but their larvae are bilateral and they are deuterostome
# bilaterians, so the radial adult is secondary. Bilaterians have one sagittal plane, anterior and
# posterior ends and dorsal and ventral sides, and three germ layers.
import wikibio as bio
from wikibio import zoology as zoo
from wikibio import zoomorph as zm

P = bio.P
fig, ax = bio.canvas(30.5, 15.2)
Y1, R1, Y2, R2 = 9.4, 2.1, 3.0, 1.45
COLS = [("Asymmetrical", "no plane", "Porifera (sponges)"), ("Radial", "4 planes (tetramerous)", "Cnidaria (moon jelly, oral view)"),
        ("Biradial", "2 planes", "Ctenophora (aboral view)"), ("Pentaradial", "5 planes (adult only)", "Echinodermata (sea star)"),
        ("Bilateral", "1 sagittal plane", "Bilateria (insect, dorsal)")]
X = [3.1 + 6.1 * i for i in range(5)]
for x, (title, planes, ex) in zip(X, COLS):
    bio.label(ax, (x, 14.8), title, size="title", bold=True)
    bio.label(ax, (x, 14.25), planes, size="small")
    bio.label(ax, (x, 13.8), ex, size="tiny", color=P.muted())

# organisms
s = zm.sponge(ax, (X[0], Y1 - 0.2), 3.6, 4.0)
bio.callout(ax, s["osculum"], (X[0] + 1.6, Y1 + 2.6), "Osculum", size="tiny")
bio.callout(ax, s["ostium"], (X[0] + 2.2, Y1 - 1.8), "Ostia", size="tiny")

m = zm.medusa(ax, (X[1], Y1), R1)
zm.planes(ax, (X[1], Y1), R1, [0, 45, 90, 135])
bio.callout(ax, m["oral_arm"], (X[1] + 1.3, Y1 + 2.7), "Oral arm", size="tiny")
bio.callout(ax, m["gonad"], (X[1] + 2.5, Y1 - 2.1), "Gonad", size="tiny")
bio.callout(ax, m["rhopalium"], (X[1] + 2.5, Y1 + 1.0), "Rhopalium", size="tiny")

c = zm.ctenophore(ax, (X[2], Y1), R1 * 0.85)
zm.planes(ax, (X[2], Y1), R1 * 1.05, [0, 90])
bio.label(ax, (X[2], Y1 + R1 * 1.2 + 0.1), "Stomodeal plane", size="tiny", color=P.muted(), va="bottom")
bio.label(ax, (X[2] + 2.3, Y1 - 0.6), "Tentacular\nplane", size="tiny", color=P.muted(), va="top")
bio.callout(ax, c["comb_row"], (X[2] + 2.2, Y1 + 2.0), "Comb row (8)", size="tiny")
bio.callout(ax, c["statocyst"], (X[2] - 2.3, Y1 + 2.1), "Apical organ", size="tiny")

st = zm.sea_star(ax, (X[3], Y1), R1)
zm.planes(ax, (X[3], Y1), R1 * 0.95, [90, 162, 54, 126, 18])
bio.callout(ax, st["madreporite"], (X[3] + 2.3, Y1 - 2.2), "Madreporite", size="tiny")

ins = zm.insect(ax, (X[4], Y1 - 0.15), 3.0, "Orthoptera", wings=False, antenna=("filiform", 0.22), cerci=0.06)
zm.planes(ax, (X[4], Y1), 2.2, [90], extend=1.0)
bio.label(ax, (X[4] + 1.7, Y1 + 1.9), "Anterior", size="tiny", color=P.muted())
bio.label(ax, (X[4] + 1.7, Y1 - 1.9), "Posterior", size="tiny", color=P.muted())

# germ layers below
bio.label(ax, (0.3, Y2 + R2 + 0.85), "Germ layers (cross-section)", size="small", bold=True, ha="left")
bio.label(ax, (X[0], Y2 + 0.2), "No true tissue layers", size="small")
bio.label(ax, (X[0], Y2 - 0.3), "(cellular grade; choanocytes)", size="tiny", color=P.muted())
zoo.body_plan(ax, (X[1], Y2), R2, "diploblast")
zoo.body_plan(ax, (X[2], Y2), R2, "diploblast")
zoo.body_plan(ax, (X[3], Y2), R2, "coelomate")
zoo.body_plan(ax, (X[4], Y2), R2, "coelomate")
for x, text in ((X[1], "Diploblastic"), (X[2], "Diploblastic"), (X[3], "Triploblastic, coelom"),
                (X[4], "Triploblastic (annelid-type\ncoelom shown)")):
    bio.label(ax, (x + R2 + 0.2, Y2 - R2 + 0.1), text, size="tiny", ha="left", va="bottom")
zoo.germ_layer_legend(ax, (X[0] - 1.2, 0.5), cavities=("coelom",), step=3.0)
